<?php
namespace App\Http\Controllers;use App\Models\Booking;use App\Models\Service;
class DashboardController extends Controller{public function index(){ $u=auth()->user();$data=[];if($u->role==='customer'){$data['upcoming']=$u->customerBookings()->with('service','provider')->whereIn('status',['pending','confirmed'])->latest()->get();$data['completed']=$u->customerBookings()->where('status','completed')->count();$data['spent']=$u->customerBookings()->where('payment_status','paid')->sum('amount');}elseif($u->role==='provider'){$data['services']=$u->services()->with('category')->latest()->get();$data['bookings']=$u->providerBookings()->with('service','customer')->latest()->get();$data['earnings']=$u->providerBookings()->where('payment_status','paid')->sum('amount');}else{$data['users']=\App\Models\User::count();$data['providers']=\App\Models\User::where('role','provider')->count();$data['bookings']=Booking::count();$data['revenue']=Booking::where('payment_status','paid')->sum('amount');}return view('dashboard',$data);}}
